import {learnerLine} from './learner-voice.js';
import {openingMystery} from './first-screens.js';
import {icon,title,next,state,save,complete,setNextVisible,toast,audio,read,escapeHTML,chime,cast,companion} from './app.js?v=8';
import {teacher,credits} from './resources.js?v=8';
import {factory,bindFactory,cleanupFactory} from './factory.js?v=9';
let timers=[],flowTimer=0;
export function cleanup(){timers.forEach(clearInterval);timers=[];clearTimeout(flowTimer);flowTimer=0;cleanupFactory()}
const needs=[['sun','Sunlight','Energy from the Sun'],['drop','Water','Absorbed through roots'],['wind','Carbon dioxide','A gas that enters leaves'],['leaf','Chlorophyll','The green substance that absorbs light']];
function diagram({light=true,water=true,co2=true,chl=true,running=false,scene=5}={}){return `<div role="img" class="leaf-world scene-${scene} ${running?'running':''}" aria-label="A model showing water and carbon dioxide entering a green plant, sunlight providing energy, and glucose and oxygen being produced"><div class="world-cloud c1"></div><div class="world-cloud c2"></div><div class="world-sun ${light?'':'missing'}">${cast('sun')}<b>Sunlight</b><small>${light?'light energy':'not available'}</small></div><div class="world-co2 ${co2?'':'missing'}"><span class="gas-bubble">CO₂</span><b>Carbon dioxide</b><small>${co2?'from the air →':'not available'}</small></div><div class="world-plant ${chl?'':'no-chlorophyll'}">${cast('sprout')}<span class="chl-tag">${chl?'Chlorophyll catches light':'No chlorophyll in this model'}</span></div><div class="world-water ${water?'':'missing'}">${cast('drop')}<div><b>Water</b><small>${water?'↑ through the roots':'not available'}</small></div></div><div class="world-products"><span class="product food">✦ <b>Food / starch</b><small>Glucose stored as starch</small></span><span class="product oxygen"><b>O₂</b><small>oxygen → air</small></span></div><div class="world-soil"></div>${running?'<span class="sparkle s1">✦</span><span class="sparkle s2">✦</span><span class="sparkle s3">✦</span>':''}</div>`}

function mystery(){return openingMystery({icon,audio,escapeHTML})}

const frames=[['Meet the leaf','Plants make their own food through photosynthesis. Most photosynthesis happens in leaves.','leaf'],['Catch the sunlight','Chlorophyll is a green substance in leaves. It absorbs light energy from the Sun.','sun'],['Bring in the raw materials','Roots absorb water. Carbon dioxide from the air enters the leaves. Water and carbon dioxide are raw materials, not ready-made food.','drop'],['Food, starch and oxygen','The textbook explains: the plant makes glucose, a sugar, and releases oxygen. Some glucose is stored as starch. The DSKP names starch and oxygen as the products.','leaf'],['A gift to living things','Plants supply food for living things. Photosynthesis adds oxygen to the air and uses carbon dioxide, helping maintain the balance of gases in the air. Plants respire during both day and night.','heart']];
let frame=0;
function story(){frame=0;return title('story','The secret inside a leaf','Follow the pictures to find out how photosynthesis works.')+`<nav class="explanation-tabs" aria-label="Ways to explore inside a leaf"><a href="#factory">${icon('play')} Play the leaf story <span>NEW</span></a><a href="#story" class="active" aria-current="page">${icon('book')} Picture notes</a></nav><section class="story-theatre"><div class="story-picture"><div id="story-diagram">${diagram({scene:0})}</div><div class="player-controls"><button id="story-back" class="icon-btn" aria-label="Previous scene">‹</button><button id="story-next" class="icon-btn" aria-label="Next scene">›</button><span id="scene-number">1 / 5</span></div></div><div class="story-copy"><div id="scene-icon" class="scene-icon">${icon('leaf')}</div><h2 id="scene-title">${frames[0][0]}</h2><p id="scene-copy">${frames[0][1]}</p><button id="scene-listen" class="audio-btn">${icon('volume')} Read it to me</button><div class="story-dots" aria-label="Story scenes">${frames.map((f,i)=>`<button data-frame="${i}" aria-label="Scene ${i+1}: ${f[0]}" class="${i===0?'active':''}">${i+1}</button>`).join('')}</div><div id="story-feedback" class="feedback" aria-live="polite"></div></div></section><details class="transcript"><summary>Story transcript & the big picture</summary>${frames.map(f=>`<h3>${f[0]}</h3><p>${f[1]}</p>`).join('')}<p><b>Water + carbon dioxide → glucose + oxygen</b><br>With light energy and chlorophyll.</p><p class="caption">Science Year 4 · Unit 4 · printed pages 76–81.</p></details>`+next('story','Let’s experiment',true)}

let lab={light:true,water:true,co2:true,chl:true},prediction='';
function labLog(){return state.labRuns.length?state.labRuns.slice(-6).map((r,i)=>`<tr><td>${i+1}</td><td>${escapeHTML(r.label)}</td><td>${r.made?'Yes':'No'}</td></tr>`).join(''):'<tr><td colspan="3">Your first experiment will appear here.</td></tr>'}
function labView(){lab={light:true,water:true,co2:true,chl:true};prediction='';return title('lab','Let’s mix, test & discover!',escapeHTML(learnerLine('{name}, can Sprout make new food if something is missing?','Can Sprout make new food if something is missing?')))+`<section class="lab-playground"><div class="lab-scene"><div id="lab-diagram">${diagram()}</div><div id="lab-output" class="lab-output" role="status">Try all four needs, then take one away.</div></div><div class="lab-tools"><h2 class="lab-instruction">1. Set up your experiment</h2><p class="lab-subinstruction">Tap a need to add or remove it.</p><div class="lab-switches">${needs.map((n,i)=>`<label class="lab-switch"><input type="checkbox" data-condition="${['light','water','co2','chl'][i]}" checked aria-label="${n[1]} available"><span class="need-art">${i===0?cast('sun'):i===1?cast('drop'):i===2?'<span class="gas-bubble">CO₂</span>':icon('leaf')}</span><strong>${n[1]}</strong></label>`).join('')}</div><fieldset class="prediction-field"><legend>2 · Will Sprout make new food?</legend><label><input type="radio" name="lab-prediction" value="yes"> I think so!</label><label><input type="radio" name="lab-prediction" value="no"> Not yet!</label></fieldset><button id="run-lab" class="btn yellow">${icon('flask')} Test my idea</button><div id="lab-feedback" class="feedback" aria-live="polite"></div></div></section><details class="transcript"><summary>My experiment notebook</summary><p>Compare a trial with all four needs and a trial with just one missing.</p><div class="table-scroll"><table><thead><tr><th>Trial</th><th>Conditions</th><th>New food?</th></tr></thead><tbody id="lab-log">${labLog()}</tbody></table></div></details><p class="caption">A simplified model. Real growth takes time. Sprout does not instantly die when photosynthesis stops.</p>`+next('lab','To the creek!',true)}

let puzzleLevel=0,rotations=[],tiles=[],moves=0,n=3,solved=false;
const puzzles=[{n:3,path:[0,1,4,3,6,7,8],name:'The meadow stream'},{n:4,path:[0,4,5,6,2,3,7,11,15],name:'The winding creek'}],dirs=[[-1,0],[0,1],[1,0],[0,-1]];
function setPuzzle(){const p=puzzles[puzzleLevel];n=p.n;tiles=Array.from({length:n*n},(_,i)=>i%3===0?[0,2]:[0,1]);rotations=Array(n*n).fill(0);moves=0;solved=false;p.path.forEach((index,k)=>{const direction=other=>{const d=other-index;return d===-n?0:d===1?1:d===n?2:3};tiles[index]=[k?direction(p.path[k-1]):3,k<p.path.length-1?direction(p.path[k+1]):1];rotations[index]=(index===0||index===n*n-1)?0:(index*7+puzzleLevel+1)%4})}
function pipeSVG(i){const ports=tiles[i].map(d=>(d+rotations[i])%4),xy=[[50,0],[100,50],[50,100],[0,50]],d=`M${xy[ports[0]].join(' ')} L50 50 L${xy[ports[1]].join(' ')}`;return `<svg viewBox="0 0 100 100" aria-hidden="true"><path class="channel" d="${d}"/><path class="water-flow" pathLength="100" d="${d}"/></svg>`}
function connected(){const visited=new Set(),path=[];const walk=(i,entry)=>{if(visited.has(i))return false;const ports=tiles[i].map(d=>(d+rotations[i])%4);if(!ports.includes(entry))return false;visited.add(i);const exit=ports.find(p=>p!==entry);path.push({i,entry,exit});if(i===n*n-1&&exit===1)return true;const[r,c]=[Math.floor(i/n)+dirs[exit][0],i%n+dirs[exit][1]];if(r<0||r>=n||c<0||c>=n)return false;return walk(r*n+c,(exit+2)%4)};const won=walk(0,3);return{won,visited,path}}
function pipeLabel(i){const ports=tiles[i].map(d=>(d+rotations[i])%4),openings=ports.map(d=>["top","right","bottom","left"][d]).join(" and ");if(i===0)return `START square. Water enters from the LEFT. Openings: ${openings}.`;if(i===n*n-1)return `ROOTS square. Water exits to the RIGHT. Openings: ${openings}.`;return `Rotate channel row ${Math.floor(i/n)+1}, column ${i%n+1} clockwise. Openings: ${openings}.`}
function pipeBoard(){return `<div class="pipe-board" style="--size:${n}" aria-label="${n} by ${n} water channel puzzle. Water flows from LEFT to RIGHT: enter at the top-left START square and exit at the bottom-right ROOTS square.">${tiles.map((_,i)=>`<button class="pipe-tile ${i===0?'is-start':i===n*n-1?'is-goal':''}" data-pipe="${i}" ${i===0||i===n*n-1?'disabled aria-disabled="true"':''} aria-label="${pipeLabel(i)}">${i===0?'<span class="pipe-marker">START</span>':i===n*n-1?'<span class="pipe-marker">ROOTS</span>':''}${pipeSVG(i)}</button>`).join('')}</div>`}
function creek(){puzzleLevel=0;setPuzzle();return title('creek','Oh no! The creek needs you.',escapeHTML(learnerLine('{name}, can you connect the stream to Sprout’s roots?','Twist the channels. Join the stream. Get water to Sprout’s roots!')))+`<section class="game-shell"><div class="game-heading"><div><h2 id="puzzle-name">The meadow stream</h2><span id="puzzle-counter" class="puzzle-count">Rescue 1 of 2</span></div><span class="move-counter">${icon('drop')} <span id="moves">0</span> twists</span></div><p class="pipe-direction">Water flows <b>LEFT to RIGHT</b>: enter at <b>START</b> (top-left), exit at <b>ROOTS</b> (bottom-right).</p><div class="creek-play"><div class="spring-label">${cast('drop')}<span class="bubble">Start here! →</span><b>SPRING</b></div><div id="pipe-area">${pipeBoard()}</div><div class="root-label">${cast('sprout')}<span class="bubble">Water, please!</span><b>→ ROOTS</b></div><div id="creek-success" class="creek-success" hidden><div class="creek-success-mark" aria-hidden="true">${icon('check')}</div><h3 id="creek-success-title" tabindex="-1">Water reached the roots!</h3><p id="creek-success-copy">You connected the stream. Sprout can absorb the water!</p><button id="next-puzzle" class="btn" hidden>Next rescue ${icon('arrow')}</button><a id="creek-continue" class="btn" href="#grove" hidden>Enter the forest ${icon('arrow')}</a></div></div><div class="game-controls"><button id="test-water" class="btn yellow">${icon('drop')} Let it flow!</button><button id="pipe-reset" class="text-btn">Start over</button><button id="pipe-hint" class="text-btn">A little hint</button></div><div id="pipe-feedback" class="feedback" aria-live="polite">Turn channels to carry water from the LEFT spring to the RIGHT roots.</div></section><p class="under-scene">${icon('lightbulb')} Roots absorb water. Leaves use it to make food. Water itself isn’t food!</p>`+next('creek','Enter the forest',true)}

function finish(){return title('finish',escapeHTML(learnerLine('High-leaf, {name}!','High-leaf, explorer!')),'Every discovery starts with a little curiosity.')+`<section class="closure-banner"><img class="celebration-art" src="assets/celebration-garden.webp" alt="Sprout and Beep celebrate their discoveries together in the garden." width="1536" height="1024"><div><h2>Plants make their own food.</h2><p>You didn't give Sprout food. You helped it get the conditions to make its own.</p></div></section><div class="lesson-columns"><section class="activity-panel"><h2>Look what you discovered!</h2><ol class="discovery-list"><li><strong>Four needs</strong><p>Sunlight, water, carbon dioxide and chlorophyll.</p></li><li><strong>Two products</strong><p>Starch (stored food) and oxygen. Plants make glucose, some of which is stored as starch.</p></li><li><strong>One wise habit</strong><p>Check a science idea against what you can observe and explain.</p></li></ol>${audio('Plants make their own food through photosynthesis. The four needs are sunlight, water, carbon dioxide and chlorophyll. The two products are glucose and oxygen. Explain your observations using science evidence.')}</section><section class="activity-panel"><h2>My field note</h2><label for="reflection">Finish one sentence: “I used to think… Now I know…”</label><textarea id="reflection" rows="4" maxlength="600" placeholder="Write about a science idea, not personal details.">${escapeHTML(state.journal)}</textarea><p class="small">Or tell your partner or teacher instead of typing.</p><div class="actions"><button id="save-reflection" class="btn">${icon('book')} Save my discovery</button><button id="spoken-reflection" class="text-btn">I shared my idea aloud</button></div><div id="reflection-feedback" class="feedback" aria-live="polite"></div></section></div><div class="notice"><strong>Take your curiosity outside</strong><p>With an adult, find two plants growing in different light. Observe their leaves. What would you keep the same in a fair test? Do not damage the plants.</p></div>`+next('finish','Open my journal',true)}
const badges=[['mystery','Curious thinker','search'],['story','Leaf explorer','leaf'],['lab','Plant scientist','flask'],['creek','Creek rescuer','drop'],['check','Knowledge grower','star'],['finish','Thoughtful explorer','flag']];
function journal(){return `<div class="page-heading"><div><h1>My field journal</h1><p>Your discoveries, gathered in one little place.</p></div><button id="download-journal" class="btn secondary">${icon('download')} Save my journal</button></div><div class="journal-sheet"><div class="journal-header">${cast('robot')}<div><h2>${state.done.length} of 6 discoveries collected</h2><p>Revisit a stop any time. There is always more to notice.</p></div></div><div class="badge-grid">${badges.map(([id,label,i])=>`<a href="#${id==='story'?'factory':id}" class="earned-badge ${state.done.includes(id)?'earned':''}"><span>${icon(i)}</span><strong>${label}</strong><small>${state.done.includes(id)?'Discovered ✓':'Waiting to be explored'}</small></a>`).join('')}</div><section class="journal-note"><h2>My reflection</h2><p>${state.journal?escapeHTML(state.journal):'Your field note will appear here after the final stop.'}</p><a href="#finish">${state.journal?'Edit my note':'Write a field note'}</a></section><a class="btn secondary" href="#certificate">${icon('download')} My discovery certificate</a><p class="journal-score">Forest adventure: <strong>${state.done.includes('check')?'Completed':'In progress'}</strong></p><p class="small">This journal stays with the selected explorer on this computer. Choose New explorer for another pupil, and download a copy to keep it.</p></div>`}
export function render(route){return ({mystery,story,factory,lab:labView,creek,finish,journal,teacher,credits}[route]||(()=>`<h1>This trail does not exist.</h1><a class="btn" href="#map">Back to the garden</a>`))()}
export function bind(route){
if(route==='factory')bindFactory();
if(route==='mystery')document.querySelectorAll('[data-predict]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-predict]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelector('#prediction-feedback').innerHTML=`<strong>${escapeHTML(learnerLine('Prediction saved, {name}. Let’s investigate!','Prediction saved. Let’s investigate!'))}</strong><p>${b.dataset.predict==='make'?'That is a promising idea. Which conditions help a leaf make food?':'Roots take in water and minerals. Our leaf story will show where the food is actually made.'}</p>`;const goals=document.querySelector('#learning-goals');goals.hidden=false;complete('mystery');document.querySelector('#learning-goals-title').focus({preventScroll:true});goals.scrollIntoView({block:'start',behavior:'instant'})});
if(route==='story'){const show=()=>{document.querySelector('#scene-title').textContent=frames[frame][0];document.querySelector('#scene-copy').textContent=frames[frame][1];document.querySelector('#scene-icon').innerHTML=icon(frames[frame][2]);document.querySelector('#scene-number').textContent=(frame+1)+' / 5';document.querySelector('#story-diagram').innerHTML=diagram({running:frame>=3,scene:frame});document.querySelectorAll('[data-frame]').forEach(b=>b.classList.toggle('active',Number(b.dataset.frame)===frame));document.querySelector('#story-back').disabled=frame===0;document.querySelector('#story-next').hidden=frame===4;if(state.settings.sound)read(frames[frame][1]);if(frame===4){complete('story');document.querySelector('#story-feedback').textContent='Sunlight, water, carbon dioxide and chlorophyll: all four help the plant make food.'}else setNextVisible('story',false)};document.querySelector('#story-next').onclick=()=>{frame=Math.min(4,frame+1);show()};document.querySelector('#story-back').onclick=()=>{frame=Math.max(0,frame-1);show()};document.querySelectorAll('[data-frame]').forEach(b=>b.onclick=()=>{frame=Number(b.dataset.frame);show()});document.querySelector('#scene-listen').onclick=()=>read(frames[frame][1]);show()}
if(route==='lab'){document.querySelectorAll('[data-condition]').forEach(c=>c.onchange=()=>{lab[c.dataset.condition]=c.checked;document.querySelector('#lab-diagram').innerHTML=diagram(lab);document.querySelector('#lab-output').textContent='Conditions changed. Make a prediction, then test.';document.querySelectorAll('[name=lab-prediction]').forEach(r=>r.checked=false);prediction=''});document.querySelectorAll('[name=lab-prediction]').forEach(r=>r.onchange=()=>prediction=r.value);document.querySelector('#run-lab').onclick=()=>{if(!prediction){document.querySelector('#lab-feedback').textContent='Choose your prediction first. Will the leaf make new food?';return}const made=Object.values(lab).every(Boolean),missing=needs.filter((_,i)=>!lab[['light','water','co2','chl'][i]]).map(x=>x[1].toLowerCase()),label=missing.length?'Missing '+missing.join(', '):'All four needs present';state.labRuns.push({label,made});state.labRuns=state.labRuns.slice(-12);save();document.querySelector('#lab-diagram').innerHTML=diagram({...lab,running:made});document.querySelector('#lab-output').textContent=made?'Glucose made → stored starch + oxygen released':'No new food made in this model';document.querySelector('#lab-feedback').innerHTML=`<strong>${(prediction==='yes')===made?'Your prediction matches the model!':'The result is different. That is a discovery!'}</strong><p>${made?'All four needs are available. The leaf can carry out photosynthesis.':'Without '+missing.join(' and ')+', the leaf cannot carry out photosynthesis in this model.'}</p>`;document.querySelector('#lab-log').innerHTML=labLog();if(state.labRuns.some(r=>r.made)&&state.labRuns.some(r=>!r.made))complete('lab')}}
if(route==='creek'){const clearFlow=()=>{clearTimeout(flowTimer);flowTimer=0;document.querySelectorAll('[data-pipe]').forEach(t=>{t.classList.remove('flowing','hinted');t.style.removeProperty('--flow-delay')});const button=document.querySelector('#test-water');if(button&&!solved)button.disabled=false};const wire=()=>document.querySelectorAll('[data-pipe]').forEach(b=>b.onclick=()=>{if(solved)return;clearFlow();const i=Number(b.dataset.pipe);rotations[i]=(rotations[i]+1)%4;moves++;document.querySelector('#moves').textContent=moves;b.innerHTML=(i===0?'<span class="pipe-marker">START</span>':i===n*n-1?'<span class="pipe-marker">ROOTS</span>':'')+pipeSVG(i);b.setAttribute('aria-label',pipeLabel(i));document.querySelector('#pipe-feedback').textContent='Channel turned. Let the water flow to try again.'});const reset=()=>{document.querySelector('#creek-success').hidden=true;document.querySelector('.creek-play').classList.remove('is-rescued');document.querySelector('.root-label .bubble').textContent='Water, please!';document.querySelector('#pipe-feedback').hidden=false;document.querySelector('#pipe-hint').disabled=false;document.querySelector('#creek-continue').hidden=true;setNextVisible('creek',false);clearFlow();setPuzzle();document.querySelector('#pipe-area').innerHTML=pipeBoard();document.querySelector('#moves').textContent='0';document.querySelector('#next-puzzle').hidden=true;document.querySelector('#test-water').disabled=false;document.querySelector('#pipe-feedback').textContent='The fixed START opens from the LEFT. Connect it to the fixed ROOTS tile on the RIGHT.';wire()};wire();document.querySelector('#pipe-reset').onclick=reset;document.querySelector('#pipe-hint').onclick=()=>{if(solved)return;clearFlow();const{visited}=connected(),last=[...visited].pop();document.querySelector('#pipe-feedback').textContent=last===undefined?'Start with the top-left channel. It needs an opening on its left side.':`Water reaches row ${Math.floor(last/n)+1}, column ${last%n+1}. Check where that channel points, and whether the next channel has an opening facing it.`;document.querySelectorAll('[data-pipe]').forEach(t=>t.classList.toggle('hinted',visited.has(Number(t.dataset.pipe))))};document.querySelector('#test-water').onclick=()=>{if(solved)return;clearFlow();const{won,path}=connected(),button=document.querySelector('#test-water'),feedback=document.querySelector('#pipe-feedback');if(!path.length){feedback.textContent='Water cannot enter the first channel. Turn it so an opening faces the spring.';return}const points=[[50,0],[100,50],[50,100],[0,50]],tilesByIndex=new Map([...document.querySelectorAll('[data-pipe]')].map(t=>[Number(t.dataset.pipe),t])),flowStep=420,flowDuration=550,stubDuration=300;document.querySelector('#pipe-area').offsetWidth;path.forEach(({i,entry,exit},order)=>{const tile=tilesByIndex.get(i);tile.querySelector('.water-flow').setAttribute('d',`M${points[entry].join(' ')} L50 50 L${points[exit].join(' ')}`);tile.style.setProperty('--flow-delay',`${stubDuration+order*flowStep}ms`);tile.classList.add('flowing')});button.disabled=true;feedback.textContent='Water is flowing…';flowTimer=window.setTimeout(()=>{flowTimer=0;if(won){solved=true;chime();button.disabled=true;if(puzzleLevel===0)document.querySelector('#next-puzzle').hidden=false;else{complete('creek');document.querySelector('#creek-continue').hidden=false}feedback.hidden=true;document.querySelector('#pipe-hint').disabled=true;document.querySelector('.root-label .bubble').textContent='Thank you! My roots have water!';document.querySelector('#creek-success-copy').textContent=puzzleLevel===0?'You connected the stream. Sprout can absorb the water!':'Both rescues complete! Sprout’s roots have water. Leaves also need sunlight, carbon dioxide and chlorophyll to make food.';document.querySelector('.creek-play').classList.add('is-rescued');document.querySelector('#creek-success').hidden=false;document.querySelector('#creek-success-title').focus({preventScroll:true});document.querySelector('#creek-success').scrollIntoView({block:'nearest',behavior:'instant'})}else{button.disabled=false;feedback.textContent='The water stopped where the route breaks. Turn a channel and try again.'}},(path.length-1)*flowStep+flowDuration+stubDuration*2)};document.querySelector('#next-puzzle').onclick=()=>{puzzleLevel=1;reset();document.querySelector('#puzzle-name').textContent=puzzles[1].name;document.querySelector('#puzzle-counter').textContent='Rescue 2 of 2'}}

if(route==='finish'){document.querySelector('#save-reflection').onclick=()=>{const value=document.querySelector('#reflection').value.trim();if(!value){document.querySelector('#reflection-feedback').textContent='Write one discovery, or share it aloud and use the button below.';return}state.journal=value;save();complete('finish');document.querySelector('#reflection-feedback').textContent='Your discovery is saved in your field journal on this device.'};document.querySelector('#spoken-reflection').onclick=()=>{complete('finish');document.querySelector('#reflection-feedback').textContent='Thank you for explaining your discovery aloud. Talking about science is learning too.'}}
if(route==='journal')document.querySelector('#download-journal').onclick=()=>{const text=`MY SPROUT LAB FIELD JOURNAL\n\nDiscoveries: ${state.done.length}/6\n${badges.map(b=>(state.done.includes(b[0])?'[Discovered] ':'[To explore] ')+b[1]).join('\n')}\n\nForest adventure: ${state.done.includes('check')?'Completed':'In progress'}\n\nMy reflection\n${state.journal||'No written reflection yet.'}\n\nPlants make their own food through photosynthesis.\n`,url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download='my-sprout-lab-journal.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
}
